<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><?php $edit=$user!==null; ?><h1><?= $edit?'Edit':'Add' ?> Staff</h1><form class="panel form" method="post" enctype="multipart/form-data" action="<?= $edit?site_url('users/'.$user['id']):site_url('users') ?>"><?= csrf_field() ?><label>Full name<input name="full_name" maxlength="100" value="<?= esc(old('full_name')??($user['full_name']??'')) ?>" required></label><label>Username<input name="username" maxlength="50" value="<?= esc(old('username')??($user['username']??'')) ?>" required></label><label>Password<input type="password" name="password" <?= $edit?'':'required' ?> minlength="8"><small><?= $edit?'Leave blank to retain the current password.':'Minimum 8 characters.' ?></small></label><label>Avatar<input type="file" name="avatar" accept="image/png,image/jpeg,image/webp"><small>JPG, PNG or WebP, maximum 2 MB.</small></label><div><button class="primary">Save Staff</button> <a class="button" href="<?= site_url('users') ?>">Cancel</a></div></form><?= $this->endSection() ?>
